242	    public List<Pet> getPets() {
243	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
244	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
245	        return Collections.unmodifiableList(sortedPets);
246	    }
247	
248	    public void setPets(List<Pet> pets) {
249	        this.pets = new HashSet<>(pets);
250	    }
