253	        getPetsInternal().add(pet);
254	        pet.setOwner(this);
255	    }
256	
257	    /**
258	     * Return the Pet with the given name, or null if none found for this Owner.
259	     *
260	     * @param name to test
261	     * @return true if pet name is already in use
262	     */
263	    public Pet getPet(String name) {
264	        return getPet(name, false);
265	    }
266	
267	    /**
268	     * Return the Pet with the given name, or null if none found for this Owner.
269	     *
270	     * @param name to test
271	     * @return true if pet name is already in use
272	     */
273	    public Pet getPet(String name, boolean ignoreNew) {
274	        name = name.toLowerCase();
275	        for (Pet pet : getPetsInternal()) {
276	            if (!ignoreNew || !pet.isNew()) {
277	                String compName = pet.getName();
278	                compName = compName.toLowerCase();
279	                if (compName.equals(name)) {
280	                    return pet;
281	                }
282	            }
283	        }
284	        return null;
285	    }
286	
287	    public Pet getPet(Integer petId) {
288	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
289	    }
290	
291	    @Override
292	    public String toString() {
293	        return new ToStringCreator(this)
294	
295	            .append("id", this.getId())
296	            .append("new", this.isNew())
297	            .append("lastName", this.getLastName())
298	            .append("firstName", this.getFirstName())
299	            .append("address", this.address)
300	            .append("city", this.city)
301	            .append("telephone", this.telephone)
302	            .toString();
303	    }
304	}
