2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * Flags a create as a soft duplicate. Runs before {@link SaveOwner}, so
10	 * {@link OwnerRepository#findAll()} returns only the owners that predate this create. A new owner
11	 * that {@link EnsureIdentityUnique} already cleared as not a hard duplicate is nonetheless a
12	 * <em>possible</em> duplicate when an existing owner shares its normalized lastName and its postcode
13	 * but carries a different telephone. On such a match it sets {@code possibleDuplicate} true and
14	 * {@code possibleDuplicateOf} to the matching owner's id (the lowest id when several match); the
15	 * owner is still created. With no match it sets {@code possibleDuplicate} false and leaves
16	 * {@code possibleDuplicateOf} null.
17	 *
18	 * <p>An owner created with {@code sharesHousehold} is a <em>declared</em> household member — it
19	 * deliberately joins an existing household — so it is never a suspected duplicate and is left
20	 * unflagged.
21	 */
22	public class FlagPossibleDuplicate {
23	
24	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository) {
25	        owner.setPossibleDuplicate(false);
26	        owner.setPossibleDuplicateOf(null);
27	
28	        // A declared household member is not a suspected duplicate.
29	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
30	            return;
31	        }
32	
33	        String postcode = owner.getPostcode();
34	        // A soft match keys on a shared postcode; an owner with no postcode cannot share one.
35	        if (postcode == null || postcode.isBlank()) {
36	            return;
37	        }
38	        String lastName = OwnerIdentity.normalizeName(owner.getLastName());
39	        String telephone = OwnerIdentity.canonicalTelephone(owner.getTelephone());
40	
41	        Owner match = null;
42	        for (Owner existing : ownerRepository.findAll()) {
43	            if (!lastName.equals(OwnerIdentity.normalizeName(existing.getLastName()))) {
44	                continue;
45	            }
46	            if (!postcode.equals(existing.getPostcode())) {
47	                continue;
48	            }
49	            if (telephone.equals(OwnerIdentity.canonicalTelephone(existing.getTelephone()))) {
50	                continue; // same telephone is not the "different telephone" soft match
51	            }
52	            if (match == null || existing.getId() < match.getId()) {
53	                match = existing;
54	            }
55	        }
56	
57	        if (match != null) {
58	            owner.setPossibleDuplicate(true);
59	            owner.setPossibleDuplicateOf(match.getId());
60	        }
61	    }
62	}
