34	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
35	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
36	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
37	    OwnerDto toOwnerDto(Owner owner);
38	
39	    /**
40	     * The owner's stored E.164 {@code telephone} formatted for humans: the '+' country code, a space,
41	     * then the national digits grouped in threes (e.g. {@code '+61 412 345 678'}). Null when no
42	     * telephone is recorded.
43	     */
44	    default String telephoneDisplay(Owner owner) {
45	        return org.springframework.samples.petclinic.rest.function.owner.OwnerTelephone.toDisplay(
46	                owner.getTelephone());
47	    }
48	
49	    /**
50	     * The owner's age band, computed from {@code birthDate} against {@code registrationDate}:
51	     * {@code MINOR} (under 18), {@code ADULT} (18-64) or {@code SENIOR} (65+). Null when no
52	     * birth date is recorded.
53	     */
54	    default String ageBand(Owner owner) {
55	        if (owner.getBirthDate() == null) {
56	            return null;
57	        }
58	        java.time.LocalDate reference = owner.getRegistrationDate() != null
59	                ? owner.getRegistrationDate() : java.time.LocalDate.now();
60	        int age = java.time.Period.between(owner.getBirthDate(), reference).getYears();
61	        if (age < 18) {
62	            return "MINOR";
63	        }
64	        if (age < 65) {
65	            return "ADULT";
66	        }
67	        return "SENIOR";
68	    }
69	
70	    /**
71	     * The owner's derived {@code identityKey} = normalizedTelephone + '|' + (email or empty) + '|' +
72	     * householdId, the single key all duplicate detection is expressed through.
73	     */
74	    default String identityKey(Owner owner) {
75	        return org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.key(
76	                owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
77	    }
