84	        return owner.getEmail() != null && !owner.getEmail().isBlank() ? "EMAIL" : "PHONE";
85	    }
86	
87	    /**
88	     * The owner's salutation: the honorific {@code title}, a single space, then the {@code lastName}
89	     * when a title is present, or just the {@code lastName} when no title is given.
90	     */
91	    default String salutation(Owner owner) {
92	        String title = owner.getTitle();
93	        if (title == null || title.isBlank()) {
94	            return owner.getLastName();
95	        }
96	        return title + " " + owner.getLastName();
97	    }
98	
99	    default String initials(Owner owner) {
100	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
101	                + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
102	    }
103	
104	    /**
105	     * The owner's locality (region), read from the REGION component of the customerCode
106	     * ({@code <REGION>-<HASH8>}); see
107	     * {@link org.springframework.samples.petclinic.rest.function.owner.OwnerRegion#regionOf}.
108	     */
109	    default String locality(Owner owner) {
110	        return org.springframework.samples.petclinic.rest.function.owner.OwnerRegion.regionOf(
111	                owner.getCustomerCode());
112	    }
113	
114	    /**
115	     * The IANA timezone name for the owner's locality (region), from the fixed region-to-timezone
116	     * table (NSW -> Australia/Sydney, VIC -> Australia/Melbourne, QLD -> Australia/Brisbane); see
117	     * {@link org.springframework.samples.petclinic.rest.function.owner.OwnerRegion#timezoneOf}.
118	     * Null when the region is absent or unknown.
119	     */
120	    default String timezone(Owner owner) {
121	        return org.springframework.samples.petclinic.rest.function.owner.OwnerRegion.timezoneOf(
122	                owner.getCustomerCode());
123	    }
124	
125	    /**
126	     * A single Luhn check digit (0-9) computed over the digits of the owner's {@code customerCode}.
127	     * Null when the customer code is absent.
128	     */
129	    default Integer checkDigit(Owner owner) {
130	        if (owner.getCustomerCode() == null) {
131	            return null;
132	        }
133	        String code = owner.getCustomerCode();
134	        int sum = 0;
135	        boolean dbl = true;
136	        for (int i = code.length() - 1; i >= 0; i--) {
137	            char c = code.charAt(i);
138	            if (c < '0' || c > '9') {
139	                continue;
140	            }
141	            int d = c - '0';
142	            if (dbl) {
143	                d *= 2;
144	                if (d > 9) {
145	                    d -= 9;
146	                }
147	            }
148	            sum += d;
149	            dbl = !dbl;
150	        }
151	        return (10 - (sum % 10)) % 10;
152	    }
153	
154	    /**
155	     * The owner's membership number, formatted {@code <customerCode>-M<YY>} where YY is the last two
156	     * digits of the registrationDate year (e.g. {@code NSW-1A2B3C4D-M26}). Null when either the customer
157	     * code or the registration date is absent.
158	     */
159	    default String membershipNumber(Owner owner) {
160	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
161	            return null;
162	        }
163	        return String.format("%s-M%02d", owner.getCustomerCode(),
164	                owner.getRegistrationDate().getYear() % 100);
165	    }
166	
167	    /**
168	     * The owner's membership points. Starts at 0; add 2 when an email is present; add 1 when the owner's
169	     * name was unique on creation (namesakeCount is 0); add 2 for a household of 3 or more members; add 3
170	     * for tenure of more than 365 days (days elapsed since the registrationDate).
171	     */
172	    static int membershipPoints(Owner owner) {
173	        int points = 0;
174	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
175	        if (hasEmail) {
176	            points += 2;
177	        }
178	        Integer namesakeCount = owner.getNamesakeCount();
179	        if (namesakeCount != null && namesakeCount == 0) {
180	            points += 1;
181	        }
182	        Integer householdSize = owner.getHouseholdSize();
183	        if (householdSize != null && householdSize >= 3) {
184	            points += 2;
185	        }
186	        if (owner.getRegistrationDate() != null
187	                && java.time.temporal.ChronoUnit.DAYS.between(
188	                        owner.getRegistrationDate(), java.time.LocalDate.now()) > 365) {
189	            points += 3;
190	        }
191	        return points;
192	    }
193	
194	    /**
195	     * The owner's membership level, derived by banding {@link #membershipPoints(Owner)}: level 1 for
196	     * 0-1 points, level 2 for 2-3, level 3 for 4-5, level 4 for 6 or more.
197	     */
198	    static int membershipLevel(Owner owner) {
199	        int points = membershipPoints(owner);
200	        if (points >= 6) {
201	            return 4;
202	        }
203	        if (points >= 4) {
204	            return 3;
205	        }
206	        if (points >= 2) {
207	            return 2;
208	        }
209	        return 1;
210	    }
